return ['domain'=>'itour-seo','plural-forms'=>'nplurals=6; plural=(n==0 ? 0 : n==1 ? 1 : n==2 ? 2 : n%100>=3 && n%100<=10 ? 3 : n%100>=11 ? 4 : 5);','language'=>'ar','project-id-version'=>'itour-seo','pot-creation-date'=>'2026-11-10T22:46:37+00:00','po-revision-date'=>'2026-11-10T22:46:37+00:00','messages'=>['iTour SEO'=>'iTour SEO','Search titles and descriptions with a live Google preview and checklist, social sharing cards, structured data for tours and excursions, indexing rules and sitemap control. Imports Yoast SEO data.'=>'عناوين وأوصاف البحث مع معاينة Google مباشرة وقائمة تحقق، وبطاقات المشاركة الاجتماعية، والبيانات المنظمة للبرامج والرحلات، وقواعد الفهرسة والتحكم في خريطة الموقع. يستورد بيانات Yoast SEO.','SEO'=>'تحسين محركات البحث','A focus keyphrase is set'=>'تم تحديد العبارة المفتاحية','The keyphrase is in the SEO title'=>'العبارة المفتاحية في عنوان البحث','The keyphrase is in the meta description'=>'العبارة المفتاحية في الوصف','The keyphrase is in the page address'=>'العبارة المفتاحية في عنوان الصفحة (الرابط)','The keyphrase is in the first paragraph'=>'العبارة المفتاحية في الفقرة الأولى','SEO title is 30–60 characters'=>'عنوان البحث بين 30 و60 حرفًا','Meta description is 120–156 characters'=>'الوصف بين 120 و156 حرفًا','The text has at least 250 words'=>'النص 250 كلمة على الأقل','Every image in the text has alt text'=>'كل صورة في النص لها نص بديل','The text links to another page of this site'=>'النص يربط بصفحة أخرى في الموقع','%d characters'=>'%d حرفًا','Focus keyphrase'=>'العبارة المفتاحية','e.g. Luxor day trip from Hurghada'=>'مثل رحلة الأقصر اليومية من الغردقة','The search phrase this page should be found for. The checklist below uses it.'=>'عبارة البحث التي يجب أن تظهر لها هذه الصفحة. تستخدمها قائمة التحقق أدناه.','SEO title'=>'عنوان البحث','Shown as the blue link in Google. Empty = the default for this content type (SEO → Settings). Variables: {title} {sep} {site} {price}.'=>'يظهر كرابط أزرق في Google. فارغ = الافتراضي لهذا النوع من المحتوى (تحسين محركات البحث ← الإعدادات). المتغيرات: {title} {sep} {site} {price}.','Meta description'=>'الوصف','The grey text under the link. Write it like a short advert: what the visitor gets and why book with you.'=>'النص الرمادي أسفل الرابط. اكتبه كإعلان قصير: ماذا يحصل الزائر ولماذا يحجز معك.','Google preview'=>'معاينة Google','Checklist'=>'قائمة التحقق','Updates as you type. Green items help this page rank; none of them is required.'=>'تتحدث أثناء الكتابة. البنود الخضراء تساعد ترتيب الصفحة؛ لا شيء منها إلزامي.','Social'=>'التواصل الاجتماعي','How the page looks when shared on Facebook, WhatsApp, LinkedIn and X. Empty fields use the SEO title, the meta description and the featured image.'=>'شكل الصفحة عند مشاركتها على فيسبوك وواتساب ولينكدإن وX. الحقول الفارغة تستخدم عنوان البحث والوصف والصورة البارزة.','Share title'=>'عنوان المشاركة','Share description'=>'وصف المشاركة','Share image'=>'صورة المشاركة','Use this image'=>'استخدم هذه الصورة','Choose image'=>'اختر صورة','Remove'=>'إزالة','Best at 1200 × 630 pixels. Empty = the featured image.'=>'الأفضل بمقاس 1200 × 630 بكسل. فارغ = الصورة البارزة.','Advanced'=>'متقدم','hidden'=>'مخفية','Search engines'=>'محركات البحث','Hide this page from search results'=>'إخفاء هذه الصفحة من نتائج البحث','Don’t follow its links'=>'عدم تتبع روابطها','Hidden pages also leave the sitemap. Use it for thank-you pages, drafts made public, duplicates.'=>'الصفحات المخفية تُحذف من خريطة الموقع أيضًا. استخدمها لصفحات الشكر والمسودات المنشورة والصفحات المكررة.','Canonical address'=>'العنوان الأساسي (Canonical)','Only when this page copies another one: the address of the original. Empty = this page’s own address.'=>'فقط عندما تنسخ هذه الصفحة صفحة أخرى: عنوان الأصل. فارغ = عنوان الصفحة نفسها.','Search results for “%s”'=>'نتائج البحث عن «%s»','Page not found'=>'الصفحة غير موجودة','Sorry, you are not allowed to do that.'=>'عذرًا، غير مسموح لك بذلك.','Settings'=>'الإعدادات','Home'=>'الرئيسية','Hide tag archives'=>'إخفاء أرشيف الوسوم','Hide blog category archives'=>'إخفاء أرشيف تصنيفات المدونة','Hide author archives'=>'إخفاء أرشيف الكتّاب','Hide date archives'=>'إخفاء أرشيف التواريخ','Keep RSS feeds out of search results'=>'إبعاد خلاصات RSS عن نتائج البحث','Deleted pages answer “410 Gone”'=>'الصفحات المحذوفة ترد بـ «410 محذوفة»','Attachment pages open the file itself'=>'صفحات المرفقات تفتح الملف نفسه','SEO settings'=>'إعدادات تحسين محركات البحث','General'=>'عام','Yoast SEO is active, so iTour SEO adds nothing to your pages yet (no double tags). Import Yoast’s data on the Import tab, then deactivate Yoast.'=>'Yoast SEO مفعّل، لذا لا يضيف iTour SEO شيئًا لصفحاتك بعد (لا وسوم مكررة). استورد بيانات Yoast من تبويب الاستيراد، ثم عطّل Yoast.','Title separator'=>'فاصل العنوان','Used by {sep} in titles, e.g. “Luxor day trip – Nile & Sea Travel”.'=>'يُستخدم في {sep} داخل العناوين، مثل «رحلة الأقصر اليومية – Nile & Sea Travel».','Home page title'=>'عنوان الصفحة الرئيسية','Variables: {site} {sep} {tagline}. A static home page can override it in its own SEO tab.'=>'المتغيرات: {site} {sep} {tagline}. يمكن لصفحة رئيسية ثابتة تجاوزه من تبويب SEO الخاص بها.','Home page description'=>'وصف الصفحة الرئيسية','About 120–156 characters: what you offer and where.'=>'نحو 120–156 حرفًا: ماذا تقدم وأين.','Content types'=>'أنواع المحتوى','Default title and description for each kind of page, used when a page leaves its own SEO fields empty. Variables: {title} {sep} {site} {excerpt} {price} (tours and excursions: the “from” price).'=>'العنوان والوصف الافتراضيان لكل نوع صفحة، يُستخدمان عندما تترك الصفحة حقول SEO الخاصة بها فارغة. المتغيرات: {title} {sep} {site} {excerpt} {price} (للبرامج والرحلات: السعر «ابتداءً من»).','Title'=>'العنوان','Description'=>'الوصف','Hide from search results'=>'إخفاء من نتائج البحث','Organization'=>'الشركة','Who runs this site. Google uses it for your knowledge panel and to link your tours to your company.'=>'من يدير هذا الموقع. يستخدمه Google للوحة المعرفة ولربط برامجك بشركتك.','Type'=>'النوع','Travel agency / DMC'=>'وكالة سفر / شركة إدارة وجهات','Local business'=>'نشاط تجاري محلي','Name'=>'الاسم','Logo'=>'الشعار','Square or wide, at least 112 × 112 pixels.'=>'مربع أو عريض، 112 × 112 بكسل على الأقل.','Phone'=>'الهاتف','With the country code, e.g. +20 100 000 0000.'=>'مع رمز الدولة، مثل ‎+20 100 000 0000.','Email'=>'البريد الإلكتروني','Social profiles'=>'حسابات التواصل الاجتماعي','One address per line: Facebook, Instagram, TikTok, YouTube, LinkedIn, TripAdvisor.'=>'عنوان في كل سطر: فيسبوك، إنستغرام، تيك توك، يوتيوب، لينكدإن، تريب أدفايزر.','Default share image'=>'صورة المشاركة الافتراضية','Used when a page has no image of its own. Best at 1200 × 630 pixels.'=>'تُستخدم عندما لا تكون للصفحة صورة خاصة. الأفضل بمقاس 1200 × 630 بكسل.','Indexing'=>'الفهرسة','Keep out of search results'=>'إبعاد عن نتائج البحث','Thin listing pages and feeds compete with the pages that sell. Search result pages are always hidden.'=>'صفحات القوائم الضعيفة والخلاصات تنافس الصفحات التي تبيع. صفحات نتائج البحث مخفية دائمًا.','Sitemap'=>'خريطة الموقع','Submit this address in Google Search Console. Hidden pages, hidden content types and the archives above are left out automatically.'=>'أرسل هذا العنوان في Google Search Console. الصفحات المخفية وأنواع المحتوى المخفية والأرشيفات أعلاه تُستبعد تلقائيًا.','Import'=>'استيراد','%d page has Yoast SEO data. Importing copies its SEO title, description, focus keyphrase, canonical, noindex and social fields into iTour SEO. Fields you already filled here are kept.'=>'%d صفحة بها بيانات Yoast SEO. الاستيراد ينسخ العناوين والأوصاف والعبارات المفتاحية والعناوين الأساسية وإعداد الإخفاء وحقول المشاركة إلى iTour SEO. الحقول التي ملأتها هنا تبقى كما هي.' . "\0" . 'صفحة واحدة بها بيانات Yoast SEO. الاستيراد ينسخ عنوانها ووصفها وعبارتها المفتاحية وعنوانها الأساسي وإعداد الإخفاء وحقول المشاركة إلى iTour SEO. الحقول التي ملأتها هنا تبقى كما هي.' . "\0" . 'صفحتان بهما بيانات Yoast SEO. الاستيراد ينسخ العناوين والأوصاف والعبارات المفتاحية والعناوين الأساسية وإعداد الإخفاء وحقول المشاركة إلى iTour SEO. الحقول التي ملأتها هنا تبقى كما هي.' . "\0" . '%d صفحات بها بيانات Yoast SEO. الاستيراد ينسخ العناوين والأوصاف والعبارات المفتاحية والعناوين الأساسية وإعداد الإخفاء وحقول المشاركة إلى iTour SEO. الحقول التي ملأتها هنا تبقى كما هي.' . "\0" . '%d صفحة بها بيانات Yoast SEO. الاستيراد ينسخ العناوين والأوصاف والعبارات المفتاحية والعناوين الأساسية وإعداد الإخفاء وحقول المشاركة إلى iTour SEO. الحقول التي ملأتها هنا تبقى كما هي.' . "\0" . '%d صفحة بها بيانات Yoast SEO. الاستيراد ينسخ العناوين والأوصاف والعبارات المفتاحية والعناوين الأساسية وإعداد الإخفاء وحقول المشاركة إلى iTour SEO. الحقول التي ملأتها هنا تبقى كما هي.','No Yoast SEO data found on this site.'=>'لا توجد بيانات Yoast SEO في هذا الموقع.','From Yoast SEO'=>'من Yoast SEO','Import Yoast data'=>'استيراد بيانات Yoast','Imported Yoast data for %d page.'=>'تم استيراد بيانات Yoast لـ %d صفحة.' . "\0" . 'تم استيراد بيانات Yoast لصفحة واحدة.' . "\0" . 'تم استيراد بيانات Yoast لصفحتين.' . "\0" . 'تم استيراد بيانات Yoast لـ %d صفحات.' . "\0" . 'تم استيراد بيانات Yoast لـ %d صفحة.' . "\0" . 'تم استيراد بيانات Yoast لـ %d صفحة.']];